        except Exception as e:
            sma = np.mean(train_values[:, i])
            forecasts[:, i] = sma
    return np.clip(forecasts, 0, None)

import numpy as np
from statsmodels.tsa.statespace.sarimax import SARIMAX
from statsmodels.tsa.holtwinters import ExponentialSmoothing
from statsmodels.tsa.arima.model import ARIMA
from sklearn.linear_model import LinearRegression
from sklearn.preprocessing import PolynomialFeatures
from sklearn.pipeline import make_pipeline

def covid_forecast(train_values, horizon, **kwargs):
    forecasts = np.zeros((horizon, train_values.shape[1]))
    random_state = kwargs.get('random_state', None)
    for i in range(train_values.shape[1]):
        try:
            model = SARIMAX(train_values[:, i], order=(1, 1, 1), seasonal_order=(1, 1, 1, 7), enforce_stationarity=False)
            results = model.fit(disp=False)
            forecast = results.forecast(steps=horizon)
        except Exception as _:
            try:
                model = ExponentialSmoothing(train_values[:, i], trend='add', seasonal='add', seasonal_periods=7)
                results = model.fit(use_boxcox=True)
                forecast = results.forecast(steps=horizon)
            except Exception as _:
                try:
                    model = ARIMA(train_values[:, i], order=(1, 1, 1))
                    results = model.fit()
                    forecast = results.forecast(steps=horizon)
                except Exception as _:
                    try:
                        model = LinearRegression()
                        X = np.arange(len(train_values)).reshape(-1, 1)
                        model.fit(X, train_values[:, i])
                        forecast = model.predict(np.arange(len(train_values), len(train_values) + horizon).reshape(-1, 1))
                    except Exception as _:
                        sma = np.mean(train_values[:, i])
                        forecast = [sma] * horizon
        forecasts[:, i] = forecast
    return np.clip(forecasts, 0, None)

